/* Racury theme — Obsidian-like knowledge graph (d3-force).
 * Data: /assets/data/graph.json, generated by _plugins/racury.rb.
 *   [data-graph="full"]  — /graph/ page, with toggles + find box.
 *   [data-graph="local"] — post sidebar, neighbourhood of data-focus.
 */
(function () {
  "use strict";

  var containers = document.querySelectorAll("[data-graph]");
  if (!containers.length || !window.d3) return;
  var d3 = window.d3;
  var reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var dataPromise = fetch(window.SITE.graph).then(function (r) { return r.json(); });

  function neighbourhood(data, focus, depth, max) {
    var keep = new Set([focus]);
    var frontier = [focus];
    for (var d = 0; d < depth; d++) {
      var next = [];
      data.links.forEach(function (l) {
        // Don't expand through category hubs past the first hop (they connect everything).
        [[l.source, l.target], [l.target, l.source]].forEach(function (pair) {
          if (frontier.indexOf(pair[0]) >= 0 && !keep.has(pair[1]) && keep.size < max) {
            if (d > 0 && pair[0].indexOf("category:") === 0) return;
            keep.add(pair[1]);
            next.push(pair[1]);
          }
        });
      });
      frontier = next;
    }
    return {
      nodes: data.nodes.filter(function (n) { return keep.has(n.id); }),
      links: data.links.filter(function (l) { return keep.has(l.source) && keep.has(l.target); })
    };
  }

  function Graph(el, raw, opts) {
    this.el = el;
    this.raw = raw;
    this.opts = opts;
    this.show = { category: true, tag: true };
    this.init();
  }

  Graph.prototype.init = function () {
    var self = this;
    var w = this.el.clientWidth || 300;
    var h = this.el.clientHeight || 300;
    this.svg = d3.select(this.el).append("svg")
      .attr("class", "graph-svg")
      .attr("viewBox", [-w / 2, -h / 2, w, h]);
    this.layer = this.svg.append("g");
    this.linkLayer = this.layer.append("g");
    this.nodeLayer = this.layer.append("g");

    this.zoom = d3.zoom().scaleExtent([0.25, 5]).on("zoom", function (e) {
      self.layer.attr("transform", e.transform);
      self.svg.classed("is-near", e.transform.k > 1.4);
      if (self.opts.mode === "full") self.svg.classed("hide-labels", !self.labels || e.transform.k < 0.6);
    });
    this.svg.call(this.zoom).on("dblclick.zoom", null);
    this.labels = true;

    var local = this.opts.mode === "local";
    this.sim = d3.forceSimulation()
      .force("link", d3.forceLink().id(function (d) { return d.id; })
        .distance(function (l) { return (l.type === "link" ? 80 : l.type === "category" ? 110 : 70) * (local ? 0.7 : 1); })
        .strength(function (l) { return l.type === "link" ? 0.8 : 0.25; }))
      .force("charge", d3.forceManyBody().strength(local ? -160 : -420))
      .force("x", d3.forceX().strength(0.05))
      .force("y", d3.forceY().strength(0.05))
      .force("collide", d3.forceCollide().radius(function (d) { return self.radius(d) + (d.type === "post" ? 18 : 8); }))
      .on("tick", function () { self.tick(); });

    this.update();
    new ResizeObserver(function () {
      var w2 = self.el.clientWidth, h2 = self.el.clientHeight;
      if (w2 && h2) self.svg.attr("viewBox", [-w2 / 2, -h2 / 2, w2, h2]);
    }).observe(this.el);
  };

  Graph.prototype.radius = function (d) {
    if (d.type === "category") return 8;
    if (d.type === "tag") return 5;
    return 5 + Math.sqrt(d.degree || 0) * 2.2;
  };

  Graph.prototype.filtered = function () {
    var self = this;
    var data = this.raw;
    if (this.opts.focus) data = neighbourhood(data, this.opts.focus, 2, 45);
    var nodes = data.nodes.filter(function (n) { return n.type === "post" || self.show[n.type]; });
    var ids = new Set(nodes.map(function (n) { return n.id; }));
    var links = data.links.filter(function (l) { return ids.has(l.source) && ids.has(l.target); });
    // Keep positions of nodes that survive a toggle so the layout doesn't jump.
    var prev = new Map((this.nodes || []).map(function (n) { return [n.id, n]; }));
    nodes = nodes.map(function (n) {
      var old = prev.get(n.id);
      return Object.assign({}, n, old ? { x: old.x, y: old.y, vx: old.vx, vy: old.vy } : {});
    });
    links = links.map(function (l) { return { source: l.source, target: l.target, type: l.type }; });
    var degree = {};
    links.forEach(function (l) {
      degree[l.source] = (degree[l.source] || 0) + 1;
      degree[l.target] = (degree[l.target] || 0) + 1;
    });
    nodes.forEach(function (n) { n.degree = degree[n.id] || 0; });
    return { nodes: nodes, links: links };
  };

  Graph.prototype.update = function () {
    var self = this;
    var data = this.filtered();
    this.nodes = data.nodes;
    this.links = data.links;

    this.adj = new Map();
    data.links.forEach(function (l) {
      [[l.source, l.target], [l.target, l.source]].forEach(function (p) {
        if (!self.adj.has(p[0])) self.adj.set(p[0], new Set());
        self.adj.get(p[0]).add(p[1]);
      });
    });

    this.linkSel = this.linkLayer.selectAll("line")
      .data(data.links, function (l) { return (l.source.id || l.source) + ">" + (l.target.id || l.target); })
      .join(
        function (enter) { return enter.append("line").attr("stroke-opacity", 0); },
        function (u) { return u; },
        function (exit) { return exit.remove(); }
      )
      .attr("class", function (l) { return "g-link g-link--" + l.type; });
    this.linkSel.transition().duration(600).attr("stroke-opacity", null);

    this.nodeSel = this.nodeLayer.selectAll("g.g-node")
      .data(data.nodes, function (d) { return d.id; })
      .join(function (enter) {
        var g = enter.append("g");
        g.each(function (d) {
          var sel = d3.select(this);
          if (d.type === "post") {
            sel.append("circle").attr("r", 0).transition().delay(Math.random() * 400).duration(700).ease(d3.easeBackOut).attr("r", self.radius(d));
          } else {
            var s = self.radius(d) * 2;
            sel.append("rect").attr("x", -s / 2).attr("y", -s / 2).attr("width", s).attr("height", s)
              .attr("transform", d.type === "category" ? "rotate(45)" : null)
              .attr("rx", d.type === "tag" ? 1.5 : 0)
              .style("opacity", 0).transition().delay(200 + Math.random() * 400).duration(600).style("opacity", 1);
          }
          sel.append("text").attr("class", "g-label")
            .attr("x", 0).attr("y", self.radius(d) + 13).attr("text-anchor", "middle")
            .text(d.title.length > 26 ? d.title.slice(0, 25) + "…" : d.title);
          sel.append("title").text(d.title);
        });
        return g;
      }, function (u) { return u; }, function (exit) { return exit.transition().duration(250).style("opacity", 0).remove(); })
      .attr("class", function (d) {
        return "g-node g-node--" + d.type + (d.id === self.opts.focus ? " g-node--focus" : "");
      })
      .style("--h", function (d) { return d.hue; })
      .on("mouseenter", function (e, d) { self.highlight(d.id); })
      .on("mouseleave", function () { self.highlight(null); })
      .on("click", function (e, d) { if (!e.defaultPrevented && d.url) window.location.href = d.url; })
      .call(d3.drag()
        .on("start", function (e, d) { if (!e.active) self.sim.alphaTarget(0.25).restart(); d.fx = d.x; d.fy = d.y; })
        .on("drag", function (e, d) { d.fx = e.x; d.fy = e.y; })
        .on("end", function (e, d) { if (!e.active) self.sim.alphaTarget(0); d.fx = null; d.fy = null; }));

    if (this.opts.focus) {
      var f = data.nodes.find(function (n) { return n.id === self.opts.focus; });
      if (f) { f.fx = 0; f.fy = 0; }
    }

    this.sim.nodes(data.nodes);
    this.sim.force("link").links(data.links);
    if (!this.fitted) {
      // Pre-settle the first layout off-screen so the view can be fitted immediately;
      // nodes still animate in (radius/opacity transitions) and keep drifting gently.
      this.fitted = true;
      this.sim.alpha(1).stop();
      for (var i = 0; i < 300; i++) this.sim.tick();
      this.tick();
      this.fit(true);
      if (!reduceMotion) this.sim.alpha(0.08).restart();
    } else {
      this.sim.alpha(reduceMotion ? 0.05 : 0.6).restart();
    }
  };

  Graph.prototype.tick = function () {
    this.linkSel
      .attr("x1", function (l) { return l.source.x; }).attr("y1", function (l) { return l.source.y; })
      .attr("x2", function (l) { return l.target.x; }).attr("y2", function (l) { return l.target.y; });
    this.nodeSel.attr("transform", function (d) { return "translate(" + d.x + "," + d.y + ")"; });
  };

  Graph.prototype.fit = function (instant) {
    if (!this.nodes.length) return;
    var xs = this.nodes.map(function (n) { return n.x; });
    var ys = this.nodes.map(function (n) { return n.y; });
    var minX = Math.min.apply(null, xs) - 40, maxX = Math.max.apply(null, xs) + 40;
    var minY = Math.min.apply(null, ys) - 40, maxY = Math.max.apply(null, ys) + 40;
    var w = this.el.clientWidth, h = this.el.clientHeight;
    var k = Math.min(2, 0.95 / Math.max((maxX - minX) / w, (maxY - minY) / h));
    var t = d3.zoomIdentity.scale(k).translate(-(minX + maxX) / 2, -(minY + maxY) / 2);
    if (instant || reduceMotion) this.svg.call(this.zoom.transform, t);
    else this.svg.transition().duration(900).call(this.zoom.transform, t);
  };

  Graph.prototype.highlight = function (id) {
    var lit = id ? new Set([id].concat(Array.from(this.adj.get(id) || []))) : null;
    this.svg.classed("has-hover", !!id);
    this.nodeSel.classed("is-lit", function (d) { return !!lit && lit.has(d.id); });
    this.linkSel.classed("is-lit", function (l) { return !!id && (l.source.id === id || l.target.id === id); });
  };

  Graph.prototype.find = function (q) {
    q = q.trim().toLowerCase();
    this.svg.classed("has-find", !!q);
    this.nodeSel.classed("is-lit", function (d) { return !!q && d.title.toLowerCase().indexOf(q) >= 0; });
    this.linkSel.classed("is-lit", false);
  };

  dataPromise.then(function (raw) {
    containers.forEach(function (el) {
      var mode = el.getAttribute("data-graph");
      var focus = el.getAttribute("data-focus");
      if (mode === "local" && !raw.nodes.some(function (n) { return n.id === focus; })) return;
      var g = new Graph(el, raw, { mode: mode, focus: mode === "local" ? focus : null });
      if (mode !== "full") return;

      document.querySelectorAll("[data-graph-toggle]").forEach(function (input) {
        input.addEventListener("change", function () {
          var key = input.getAttribute("data-graph-toggle");
          if (key === "labels") {
            g.labels = input.checked;
            g.svg.classed("hide-labels", !input.checked);
          } else {
            g.show[key] = input.checked;
            g.update();
          }
        });
      });
      var find = document.querySelector("[data-graph-find]");
      if (find) find.addEventListener("input", function () { g.find(find.value); });
    });
  }).catch(function () {});
})();
